import json, os, glob
results = {}
for f in sorted(glob.glob('/root/autodl-tmp/gen-depth-contamination/results/deberta_cross_transfer/*.json')):
    d = json.load(open(f))
    name = os.path.basename(f).replace('.json','')
    results[name] = {'kstar': d['kstar'], 'train': d['train_model'], 'test': d['test_model'], 'elapsed': d.get('elapsed_seconds',0)}
    # Get AUC from pairwise 0v1
    p = d.get('pairwise',{})
    results[name]['auc_0v1'] = p.get('0v1',{}).get('auc','?')

for k,v in results.items():
    print(f'{v[\"train\"]:>15} -> {v[\"test\"]:<15} K*={v[\"kstar\"]}  AUC(0v1)={v[\"auc_0v1\"]}  elapsed={v[\"elapsed\"]:.0f}s')

# Check missing pairs
models = ['wiki_pythia','wiki_olmo','wiki_qwen7b','wiki_llama8b']
expected = set()
for a in models:
    for b in models:
        if a != b:
            expected.add((a,b))
found = set((v['train'],v['test']) for v in results.values())
found_expected = found & expected
missing = expected - found
extra = found - expected
print(f'\nExpected: {len(expected)}, Found (in expected set): {len(found_expected)}, Missing: {len(missing)}, Extra: {len(extra)}')
for m in sorted(missing):
    print(f'  MISSING: {m[0]} -> {m[1]}')
for e in sorted(extra):
    print(f'  EXTRA: {e[0]} -> {e[1]}')
"
